(async()=>{
  const page=figma.getNodeById('17:2');
  // IDs
  const HOME='24:28', SHOP='26:70', PROD='31:147', DRAWER='35:181', CMP='35:227', CART='36:269', CHK='36:356', CONTACT='37:391', BLOG='37:489';

  // Find Footer component, add a "Blog" link under Links/Contact
  let footerComp=null;
  (function walk(n){ if(!n||!('children' in n))return; for(const c of n.children){ if(c.type==='COMPONENT' && c.name.indexOf('Footer')>=0){footerComp=c;} walk(c);} })(page);

  let blogErr=null;
  if(footerComp){
    try{
      await figma.loadFontAsync({family:'Poppins',style:'Medium'});
      // find the Contact text child for position reference
      let contact=null; let links=null;
      (function walk(n){ if(!n||!('children' in n))return; for(const c of n.children){ if(c.type==='TEXT' && c.characters==='Contact')contact=c; if(c.type==='TEXT' && c.characters==='Links')links=c; walk(c);} })(footerComp);
      let y = contact ? contact.y+26 : (links? links.y+26*4 : 0);
      const blog=figma.createText();
      blog.characters='Blog';
      blog.fontName={family:'Poppins',style:'Medium'};
      blog.fontSize=16; blog.fills=[{type:'SOLID',color:{r:0.62,g:0.62,b:0.62}}];
      blog.x = contact? contact.x : 20;
      blog.y = contact? contact.y+26 : y;
      footerComp.appendChild(blog);
    }catch(e){ blogErr=String(e.message); }
  }

  // helper: set single click->navigate reaction
  function react(node, dest){
    if(!node || node.type==='DOCUMENT') return false;
    try{
      node.reactions=[{ action:{type:'NODE', destinationId:dest}, trigger:{type:'ON_CLICK'}, transition:{type:'DISSOLVE', duration:300, easing:'EASE_OUT'} }];
      return true;
    }catch(e){ return false; }
  }

  const log=[];
  function findHeader(frame){ for(const c of frame.children){ if(c.type==='INSTANCE' && /^Header/.test(c.name)) return c; } return null; }
  function findFooter(frame){ for(const c of frame.children){ if(c.type==='INSTANCE' && /^Footer/.test(c.name)) return c; } return null; }
  function childrenOf(n){ return (n && 'children' in n)?Array.from(n.children):[]; }
  function findChild(inst,pred){ for(const c of childrenOf(inst)){ if(pred(c)) return c; } return null; }

  function wireHeader(frame, opts){
    const h=findHeader(frame); if(!h){ log.push(frame.name+':no header'); return; }
    if(opts.home!==undefined){ const t=findChild(h,c=>c.type==='TEXT'&&c.characters==='Home'); if(t&&react(t,opts.home)) log.push(frame.name+':nav Home'); }
    if(opts.shop!==undefined){ const t=findChild(h,c=>c.type==='TEXT'&&c.characters==='Shop'); if(t&&react(t,opts.shop)) log.push(frame.name+':nav Shop'); }
    if(opts.about!==undefined){ const t=findChild(h,c=>c.type==='TEXT'&&c.characters==='About'); if(t)react(t,opts.about); }
    if(opts.contact!==undefined){ const t=findChild(h,c=>c.type==='TEXT'&&c.characters==='Contact'); if(t&&react(t,opts.contact)) log.push(frame.name+':nav Contact'); }
    if(opts.cart!==undefined){ const ic=findChild(h,c=>c.type==='INSTANCE'&&/Icon_Cart/.test(c.name)); if(ic&&react(ic,opts.cart)) log.push(frame.name+':cart'); }
  }
  function wireFooter(frame){
    const f=findFooter(frame); if(!f)return;
    const opts={home:HOME, shop:SHOP};
    const homeT=findChild(f,c=>c.type==='TEXT'&&c.characters==='Home'); if(homeT)react(homeT,opts.home);
    const shopT=findChild(f,c=>c.type==='TEXT'&&c.characters==='Shop'); if(shopT)react(shopT,opts.shop);
    const contactT=findChild(f,c=>c.type==='TEXT'&&c.characters==='Contact'); if(contactT)react(contactT,CONTACT);
    const blogT=findChild(f,c=>c.type==='TEXT'&&c.characters==='Blog'); if(blogT)react(blogT,BLOG);
    log.push(frame.name+':footer wired');
  }
  function wirePageTitleHome(frame){
    const pt=childrenOf(frame).find(c=>c.type==='INSTANCE'&&/^PageTitle/.test(c.name));
    if(!pt)return;
    const t=findChild(pt,c=>c.type==='TEXT'&&c.characters==='Home');
    if(t)react(t,HOME);
  }

  function getById(id){ return figma.getNodeById(id); }
  const F={};
  for(const k of ['HOME','SHOP','PROD','DRAWER','CMP','CART']) F[k]=getById({HOME,SHOP,PROD,DRAWER,CMP,CART}[k]);

  // ---------- 01_Home ----------
  const home=getById(HOME);
  wireHeader(home,{shop:SHOP,contact:CONTACT,cart:CART});
  react(getById('24:53'),SHOP);              // BUY NOW
  react(getById('24:145'),SHOP);             // Show More
  // product cards -> product
  ['24:70','24:79','24:97','24:106','24:114','24:120','24:128','24:137'].forEach(id=>react(getById(id),PROD));
  // Leviosa hover Compare -> comparison
  react(getById('24:93'),CMP);
  wireFooter(home);

  // ---------- 02_Shop ----------
  const shop=getById(SHOP);
  wireHeader(shop,{home:HOME,contact:CONTACT,cart:CART});
  wirePageTitleHome(shop);
  // 16 product cards -> product
  ['26:118','26:127','26:145','26:154','26:162','26:168','26:188','26:197','26:205','26:214','26:232','26:241','26:249','26:255'].forEach(id=>react(getById(id),PROD));
  // Leviosa hover compare -> comparison (frame 26:141)
  react(getById('26:141'),CMP);
  wireFooter(shop);

  // ---------- 03_Product ----------
  const pro=getById(PROD);
  wireHeader(pro,{home:HOME,contact:CONTACT,cart:CART});
  react(getById('31:166'),SHOP);             // breadcrumb -> Shop
  react(getById('31:213'),DRAWER);           // Add To Cart -> drawer
  react(getById('31:215'),CMP);              // + Compare -> comparison
  // related product cards -> product
  ['31:241','31:250','31:256','31:265'].forEach(id=>react(getById(id),PROD));
  wireFooter(pro);

  // ---------- 04_Cart_Drawer ----------
  const draw=getById(DRAWER);
  react(getById('35:222'),CART);    // Cart -> 06_Cart
  react(getById('35:224'),CHK);     // Checkout -> 07_Checkout
  react(getById('35:226'),CMP);     // Comparison -> 05_Comparison
  react(getById('35:204'),PROD);    // close -> product

  // ---------- 05_Comparison ----------
  const cmp=getById(CMP);
  wireHeader(cmp,{home:HOME,contact:CONTACT,cart:CART});
  wirePageTitleHome(cmp);
  react(getById('35:255'),SHOP);    // View More -> shop
  react(getById('35:279'),CART);    // Add To Cart Asgaard
  react(getById('35:296'),CART);    // Add To Cart Outdoor
  wireFooter(cmp);

  // ---------- 06_Cart ----------
  const cartf=getById(CART);
  wireHeader(cartf,{home:HOME,contact:CONTACT,cart:CART});
  wirePageTitleHome(cartf);
  react(getById('36:317'),CHK);     // Check Out -> checkout
  react(getById('36:302'),PROD);    // product row -> product
  wireFooter(cartf);

  // ---------- 07_Checkout ----------
  const chk=getById(CHK);
  wireHeader(chk,{home:HOME,contact:CONTACT,cart:CART});
  wirePageTitleHome(chk);
  wireFooter(chk);

  // ---------- 08_Contact ----------
  const ct=getById(CONTACT);
  wireHeader(ct,{home:HOME,cart:CART});
  wirePageTitleHome(ct);
  wireFooter(ct);

  // ---------- 09_Blog ----------
  const bl=getById(BLOG);
  wireHeader(bl,{home:HOME,cart:CART});
  wirePageTitleHome(bl);
  wireFooter(bl);

  return {blogErr, wiredCount:log.length, sample:log.slice(0,40)};
