  const cmp=figma.getNodeById('35:227');
  const map=(f)=>{
    const arr=[];
    (function walk(n,d){ if(!n||!('children' in n)||d>4)return; for(const c of n.children){
      if(c.type==='COMPONENT')continue;
      let l='';
      if(c.type==='TEXT')l='T:"'+c.characters.slice(0,18)+'"';
      else if(c.type==='INSTANCE')l='I:'+(c.mainComponent?c.mainComponent.name:c.name);
      else if(c.type==='FRAME')l='F:'+c.name;
      else if(c.type==='RECTANGLE')l='⬛'+(c.name?' '+c.name:'');
      else l=c.type+(c.name?' '+c.name:'');
      arr.push(' '.repeat(d)+c.id+' '+l+' w'+Math.round(c.width)+' h'+Math.round(c.height));
      walk(c,d+1);
    }})(f,0);
    return arr;
  };
  return {drawer:map(drawer), cmp:map(cmp)};
})();

(async()=>{
  const D={product:'31:147',cart:'36:269',checkout:'36:356',cmp:'35:227',shop:'26:70',home:'24:28'};
  const wire=(id,to)=>{const n=figma.getNodeById(id); if(!n)return {id,err:'missing'}; n.reactions=[{actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:to,transition:null,resetVideoPosition:false}],trigger:{type:'ON_CLICK'}}]; return {id,to};};
  const out=[];
  // --- 04 Cart Drawer ---
  out.push(wire('35:221',D.cart));     // Cart button
  out.push(wire('35:223',D.checkout)); // Checkout button
  out.push(wire('35:225',D.cmp));      // Comparison button
  out.push(wire('35:204',D.product));  // close -> product
  // --- 05 Comparison ---
  out.push(wire('35:255',D.shop));     // View More -> shop
  out.push(wire('35:279',D.cart));     // Add To Cart (Asgaard) -> cart
  out.push(wire('35:296',D.cart));     // Add To Cart (Outdoor) -> cart
  // breadcrumb Home in PageTitle instance (35:245)
  const pt=figma.getNodeById('35:245');
  let homeTxt=null;
  (function walk(n){ if(!n||!('children' in n))return; for(const c of n.children){ if(c.type==='TEXT'&&c.characters==='Home'){homeTxt=c;return;} walk(c);} })(pt);
  if(homeTxt){ homeTxt.reactions=[{actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:D.home,transition:null,resetVideoPosition:false}],trigger:{type:'ON_CLICK'}}]; out.push('cmpBreadcrumbHome'); }
  return {out};
})();

(async()=>{
  const frames={cart:'36:269',checkout:'36:356',contact:'37:391',blog:'37:489'};
  const out={};
  for(const[kn,id]of Object.entries(frames)){
    const f=figma.getNodeById(id);
    const arr=[];
    (function walk(n,d){ if(!n||!('children' in n)||d>4)return; for(const c of n.children){
      if(c.type==='COMPONENT')continue;
      let l='';
      if(c.type==='TEXT')l='T:"'+c.characters.slice(0,22)+'"';
      else if(c.type==='INSTANCE')l='I:'+(c.mainComponent?c.mainComponent.name:c.name);
      else if(c.type==='FRAME')l='F:'+c.name;
      else if(c.type==='RECTANGLE')l='⬛'+(c.name?' '+c.name:'');
      else l=c.type+(c.name?' '+c.name:'');
      arr.push(' '.repeat(d)+c.id+' '+l);
      walk(c,d+1);
    }})(f,0);
    out[kn]=arr;
  }
  return out;
})();

(async()=>{
  const D={home:'24:28',product:'31:147',checkout:'36:356',contact:'37:391',blog:'37:489'};
  const wire=(id,to)=>{const n=figma.getNodeById(id); if(!n)return {id,err:'missing'}; n.reactions=[{actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:to,transition:null,resetVideoPosition:false}],trigger:{type:'ON_CLICK'}}]; return {id,to};};
  const wireBreadcrumb=(ptId,homeDest)=>{const pt=figma.getNodeById(ptId); let t=null; (function walk(n){if(!n||!('children' in n))return; for(const c of n.children){if(c.type==='TEXT'&&c.characters==='Home'){t=c;return;} walk(c); }})(pt); if(t){t.reactions=[{actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:homeDest,transition:null,resetVideoPosition:false}],trigger:{type:'ON_CLICK'}}]; return true;} return false;};
  const out=[];
  // --- 06 Cart ---
  out.push(wire('36:318',D.checkout));  // Check Out -> checkout
  out.push(wire('36:304',D.product));    // Asgaard sofa -> product
  out.push({breadcrumbCart:wireBreadcrumb('36:287',D.home)});
  // --- 07 Checkout breadcrumb ---
  out.push({breadcrumbCheckout:wireBreadcrumb('36:374',D.home)});
  // --- 08 Contact breadcrumb ---
  out.push({breadcrumbContact:wireBreadcrumb('37:410',D.home)});
  // --- 09 Blog breadcrumb ---
  out.push({breadcrumbBlog:wireBreadcrumb('37:507',D.home)});
  return out;
})();

(async()=>{
  const home=figma.getNodeById('24:28');
  const res=[];
  (function walk(n,d){
    if(!n||!('children' in n))return;
    for(const c of n.children){
      if(c.reactions && c.reactions.length){ res.push({id:c.id, type:c.type, name:c.name, n:c.reactions.length, dest:c.reactions[0].actions[0].destinationId}); }
      walk(c,d+1);
    }
  })(home,0);
  return {homeReactions:res};
})();

(async()=>{
  const frames=['26:70','31:147','35:181','35:227'];
  const res=[];
  for(const fid of frames){
    const f=figma.getNodeById(fid);
    let cnt=0; const list=[];
    (function walk(n,d){ if(!n||!('children' in n))return; for(const c of n.children){ if(c.reactions&&c.reactions.length){cnt++; list.push(c.id+' '+(c.name||'')+'→'+c.reactions[0].actions[0].destinationId);} walk(c,d+1);} })(f,0);
    res.push({frame:fid, count:cnt, list:list.slice(0,40)});
  }
  return res;
})();

